import{_ as s,a0 as u,w as a,s as l,ao as p,I as r,x as e,a1 as o,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用6款卓爾不羣的Linux操作系統為你的上網本添活力 | LCTT x X-CMD","titleTemplate":false,"description":"使用6款卓爾不羣的Linux操作系統為你的上網本添活力 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用6款卓爾不羣的Linux操作系統為你的上網本添活力 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用6款卓爾不羣的Linux操作系統為你的上網本添活力 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/6 Unusual Yet Great Linux Operating Systems For Your Netbook!","title":"使用6款卓爾不羣的Linux操作系統為你的上網本添活力","tag":"201402","desc":""},"relativePath":"201402/6 Unusual Yet Great Linux Operating Systems For Your Netbook!.md","filePath":"[post].md"}'),m={name:"201402/6 Unusual Yet Great Linux Operating Systems For Your Netbook!.md"};function d(x,t,L,g,f,T){const n=u("Link");return a(),l("div",null,[t[11]||(t[11]=p('<h1 id="使用6款卓爾不羣的linux操作系統為你的上網本添活力" tabindex="-1">使用6款卓爾不羣的Linux操作系統為你的上網本添活力 <a class="header-anchor" href="#使用6款卓爾不羣的linux操作系統為你的上網本添活力" aria-label="Permalink to “使用6款卓爾不羣的Linux操作系統為你的上網本添活力”">​</a></h1><blockquote><p>基於Linux的操作系統的優點是它們可以根據不同的需求定製。因此，在這裏我們將為您呈現6款專為上網本設計不同於其它而又有趣的頂尖發行版。</p></blockquote><p>評定一款上網本的OS是否良好，主要取決於它能否“物盡其用”。當在閒置模式下,內存使用應該降到最小限度，你需要一個很好的導航系統來避免屏幕的錯亂。</p><p>對於一名 Linux 愛好者來説，擁有一款對本本優化過的操作系統，同時還是基於開源技術，這該有多好啊。</p><p><img src="http://1-ps.googleusercontent.com/h/www.efytimes.com/admin/useradmin/photo/150x150xlU3z33744PM1132014.jpg.pagespeed.ic.3AoI0od5vQ.jpg" alt=""></p><ol><li><p><strong>AntiX</strong> - 利用了 iceWM 窗口管理器，能幫助維持初始內存的低佔用。雖然它並不像 Ubuntu, Mint 和 Elementary 那樣風靡，但是它功能齊全。在底部有一個導航任務欄，桌面上的標準跨操作系統圖標已經存在數年之久。AntiX 帶有一系列的應用程序，其中有少部分不太適合用於上網本。</p></li><li><p><strong>SparkyLinux</strong> - Razor-Qt 的外觀和體驗是非常傳統的，底部有一個面板，菜單位於底部的左下角。SparkyLinux 帶有一系列應用程序。開發者再次選擇了 LibreOffice 套件，而不是更加輕量的 Abiword 和 Gnumeric 工具包。</p></li><li><p><strong>Lubuntu</strong> - LXDE 桌面非常的輕量，也近乎 Xubuntu 那麼容易定製。這桌面在熟悉不過了，在底部有一個面板帶有菜單和系統托盤圖標。不過，你可以根據自己需要多面板自定義 Lubuntu 外觀。Sylpheed 郵件客户端，火狐瀏覽器，以及 Abiword 和 Gnumeric ，這些應用程序對於上網本來説在合適不過了。</p></li><li><p><strong>OS4</strong> - 基於 Xubuntu。使用了 XFCE 桌面，完美定製，你可以嘗試任何一種方式來工作。XFCE 是一款輕量級的桌面環境，在上網本上運行極佳。然而，你需要安裝額外的限制包來播放 Flash 視頻和 MP3 , 但是OS4會讓這些立馬工作。同時安裝有 Commodore Amiga 模擬器，你如果喜歡在你的上網本上嘗試一款經典復古遊戲，這是個再好不過的選項。</p></li><li><p><strong>Point Linux</strong> - 它使用了MATE桌面，使它變得更加獨特。MATE 桌面最初源於 GNOME2 ,但是現在它已經憑藉自身發展成一個真正優秀的桌面環境。Point Linux 外觀看起來非常時尚。菜單看起來非常好，在上網本上的執行效率也很高。類似於 LXDE 和 XFCE 桌面，它也有很高的定製性。Point Linux 默認帶有 4 個虛擬工作區，允許你最大限度的使用你的上網本，因此它受到內存和處理器處理顯示問題的限制。</p></li><li><p><strong>Elementary OS</strong> - 如果你在尋找一些非常時尚的東西，那麼這款絕對適合你。它沒有安裝 Office 套件，但是你可以挑選你想要的工具。對於網頁瀏覽器你可以用 Midori，郵件客户端可以用 Geary。安裝有用來觀看視頻的 Totem 以及一款名為 Noise的緊湊型音頻應用程序。</p></li></ol><p>來源： eyerydaylinuxuser.com</p><hr>',8)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://www.efytimes.com/e1/fullnews.asp?edid=126643"},{default:i(()=>[...t[0]||(t[0]=[e("http://www.efytimes.com/e1/fullnews.asp?edid=126643",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("譯者：",-1)),o(n,{href:"https://github.com/Luoxcat"},{default:i(()=>[...t[2]||(t[2]=[e("Luoxcat",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),o(n,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:i(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const _=s(m,[["render",d]]);export{y as __pageData,_ as default};
